// classes.js - 三职业数值与技能表（纯数据+纯函数，无副作用）
export const CLASSES = {
  warrior: {
    id: 'warrior', name: '剑士', role: '近战坦',
    base: { hp: 120, mp: 40, atk: 12, def: 8, crit: 0.05, moveSpeed: 180 },
    attack: { type: 'melee', combo: 3, range: 48, frame: 12 },
    skills: [
      { id: 'whirlwind', name: '旋风斩', mp: 12, cd: 6, mult: 1.8, radius: 72 },
      { id: 'shieldCharge', name: '盾冲', mp: 10, cd: 8, mult: 1.4, dash: 160 }
    ],
    soloFriendly: 'high'
  },
  mage: {
    id: 'mage', name: '法师', role: '远程爆发',
    base: { hp: 80, mp: 100, atk: 16, def: 4, crit: 0.08, moveSpeed: 170 },
    attack: { type: 'projectile', range: 320, speed: 420, frame: 14 },
    skills: [
      { id: 'firewall', name: '火墙', mp: 20, cd: 9, mult: 0.6, duration: 4, tick: 0.5 },
      { id: 'frostRing', name: '冰环', mp: 18, cd: 7, mult: 1.2, radius: 96, slow: 0.4 }
    ],
    soloFriendly: 'medium'
  },
  ranger: {
    id: 'ranger', name: '游侠', role: '灵活持续',
    base: { hp: 95, mp: 60, atk: 13, def: 5, crit: 0.12, moveSpeed: 200 },
    attack: { type: 'projectile', range: 360, speed: 520, frame: 10 },
    skills: [
      { id: 'backstepShot', name: '后跳射击', mp: 8, cd: 5, mult: 1.3, dash: -120 },
      { id: 'arrowRain', name: '箭雨', mp: 22, cd: 10, mult: 0.5, duration: 3, tick: 0.4, radius: 120 }
    ],
    soloFriendly: 'medium'
  }
};

export function getClass(id) {
  const c = CLASSES[id];
  if (!c) throw new Error('unknown class: ' + id);
  return c;
}

export function listClasses() {
  return Object.values(CLASSES).map(c => ({ id: c.id, name: c.name, role: c.role, soloFriendly: c.soloFriendly }));
}

// combat.js - 伤害公式/无敌帧/技能CD/顿帧（纯函数，无副作用）
// 伤害公式：base = atk * mult * (1 + critBonus)；减伤 = def / (def + 50)；最终 = base * (1 - 减伤)
// 暴击：roll < crit 时 ×1.5
export const HITSTOP_MS = 80;
export const DODGE_INVULN_MS = 300;

export function mitigation(def) {
  const d = Math.max(0, def || 0);
  return d / (d + 50);
}

export function computeDamage({ atk, mult = 1, def = 0, crit = 0, critMult = 1.5, roll = 1 }) {
  if (atk < 0) throw new Error('atk must be >= 0');
  const isCrit = roll < crit;
  const raw = atk * mult * (isCrit ? critMult : 1);
  const dmg = Math.max(1, Math.round(raw * (1 - mitigation(def))));
  return { damage: dmg, isCrit };
}

export function createCooldowns() {
  return { map: Object.create(null) };
}

export function tickCooldowns(cd, dtMs) {
  for (const k of Object.keys(cd.map)) {
    cd.map[k] = Math.max(0, cd.map[k] - dtMs);
  }
}

export function canUseSkill(cd, skillId) {
  return (cd.map[skillId] || 0) <= 0;
}

export function startCooldown(cd, skillId, cdMs) {
  cd.map[skillId] = cdMs;
}

export function isInvulnerable(entity, nowMs) {
  return (entity.invulnUntil || 0) > nowMs;
}

export function applyDodge(entity, nowMs) {
  entity.invulnUntil = nowMs + DODGE_INVULN_MS;
  return entity.invulnUntil;
}

export function hitstop() {
  return HITSTOP_MS;
}

// player.js - 玩家状态与输入意图→动作（纯逻辑，无副作用）
import { getClass } from './classes.js';
import { createCooldowns, tickCooldowns, canUseSkill, startCooldown, applyDodge, isInvulnerable } from './combat.js';

export function createPlayer({ id = 'p1', classId = 'warrior', x = 0, y = 0 } = {}) {
  const c = getClass(classId);
  return {
    id, classId,
    x, y, vx: 0, vy: 0, facing: 1,
    hp: c.base.hp, maxHp: c.base.hp,
    mp: c.base.mp, maxMp: c.base.mp,
    atk: c.base.atk, def: c.base.def, crit: c.base.crit, moveSpeed: c.base.moveSpeed,
    cooldowns: createCooldowns(),
    invulnUntil: 0,
    state: 'idle',
    potions: 3
  };
}

export function stepPlayer(p, intent, dtMs, nowMs) {
  tickCooldowns(p.cooldowns, dtMs);
  const dt = dtMs / 1000;
  if (intent.left) { p.vx = -p.moveSpeed; p.facing = -1; }
  else if (intent.right) { p.vx = p.moveSpeed; p.facing = 1; }
  else p.vx = 0;
  p.x += p.vx * dt;
  if (intent.jump && p.state !== 'air') { p.vy = -420; p.state = 'air'; }
  if (p.state === 'air') { p.vy += 1200 * dt; p.y += p.vy * dt; if (p.y >= 0) { p.y = 0; p.vy = 0; p.state = 'idle'; } }
  if (intent.dodge) applyDodge(p, nowMs);
  if (intent.potion && p.potions > 0) { p.potions--; p.hp = Math.min(p.maxHp, p.hp + Math.round(p.maxHp * 0.3)); }
  if (intent.skill) {
    const sk = getClass(p.classId).skills.find(s => s.id === intent.skill);
    if (sk && canUseSkill(p.cooldowns, sk.id) && p.mp >= sk.mp) {
      p.mp -= sk.mp;
      startCooldown(p.cooldowns, sk.id, sk.cd * 1000);
      p.state = 'skill';
    }
  }
  return p;
}

export function takeDamage(p, dmg, nowMs) {
  if (isInvulnerable(p, nowMs)) return { applied: 0, dead: false };
  p.hp = Math.max(0, p.hp - dmg);
  return { applied: dmg, dead: p.hp <= 0 };
}

// enemies.js - 普通怪4类+精英词缀+Boss三阶段骨架+仇恨（纯逻辑）
import { computeDamage } from './combat.js';

export const ENEMY_TYPES = {
  charger: { id: 'charger', hp: 40, atk: 8, def: 2, speed: 120, behavior: 'charge' },
  thrower: { id: 'thrower', hp: 30, atk: 10, def: 1, speed: 80, behavior: 'ranged' },
  flyer: { id: 'flyer', hp: 25, atk: 7, def: 0, speed: 160, behavior: 'fly' },
  bomber: { id: 'bomber', hp: 20, atk: 14, def: 0, speed: 100, behavior: 'explode' }
};

export const ELITE_AFFIXES = ['shield', 'haste', 'split', 'lifesteal'];

export function createEnemy(typeId, { elite = false, affixes = [], x = 0, y = 0 } = {}) {
  const t = ENEMY_TYPES[typeId];
  if (!t) throw new Error('unknown enemy: ' + typeId);
  const hpMult = elite ? 2.2 : 1;
  return {
    id: typeId + '_' + Math.random().toString(36).slice(2, 8),
    type: typeId, elite, affixes: elite ? affixes.slice(0, 2) : [],
    x, y, hp: Math.round(t.hp * hpMult), maxHp: Math.round(t.hp * hpMult),
    atk: t.atk, def: t.def, speed: t.speed, behavior: t.behavior,
    phase: 1, state: 'patrol'
  };
}

export function createBoss({ x = 0, y = 0 } = {}) {
  return {
    id: 'boss', type: 'boss', elite: false, affixes: [],
    x, y, hp: 800, maxHp: 800, atk: 20, def: 10, speed: 90,
    phase: 1, state: 'idle', phases: [1, 2, 3]
  };
}

export function updateBossPhase(boss) {
  const r = boss.hp / boss.maxHp;
  boss.phase = r > 0.66 ? 1 : r > 0.33 ? 2 : 3;
  return boss.phase;
}

export function pickTarget(enemies, players) {
  // 仇恨：最近优先，其次伤害最高（简化：最近）
  let best = null, bestD = Infinity;
  for (const e of enemies) {
    for (const p of players) {
      const d = Math.abs(e.x - p.x) + Math.abs(e.y - p.y);
      if (d < bestD) { bestD = d; best = p; }
    }
  }
  return best;
}

export function enemyAttack(enemy, target, roll = 1) {
  return computeDamage({ atk: enemy.atk, mult: 1, def: target.def || 0, crit: 0, roll });
}

// items.js - 装备生成/强化/重铸（纯逻辑，注入 rng）
export const SLOTS = ['weapon', 'helmet', 'armor', 'boots', 'accessory'];
export const QUALITIES = ['white', 'green', 'blue', 'purple', 'orange'];
export const QUALITY_WEIGHTS = { white: 40, green: 30, blue: 20, purple: 8, orange: 2 };
export const AFFIX_KEYS = ['atk', 'crit', 'atkSpeed', 'hp', 'moveSpeed', 'cdr', 'goldGain'];

export function rollQuality(rng, weights = QUALITY_WEIGHTS) {
  const total = Object.values(weights).reduce((a, b) => a + b, 0);
  let r = rng() * total;
  for (const q of QUALITIES) {
    r -= weights[q];
    if (r <= 0) return q;
  }
  return 'white';
}

export function rollAffixes(rng, count) {
  const pool = AFFIX_KEYS.slice();
  const out = [];
  for (let i = 0; i < count && pool.length; i++) {
    const idx = Math.floor(rng() * pool.length);
    const key = pool.splice(idx, 1)[0];
    out.push({ key, value: Math.round((0.5 + rng() * 2) * 100) / 100 });
  }
  return out;
}

export function createItem({ rng = Math.random, slot, quality, classRestrict = null } = {}) {
  const s = slot || SLOTS[Math.floor(rng() * SLOTS.length)];
  const q = quality || rollQuality(rng);
  const affixCount = 2 + Math.floor(rng() * 3); // 2-4
  return {
    id: 'it_' + Math.random().toString(36).slice(2, 10),
    slot: s, quality: q,
    affixes: rollAffixes(rng, affixCount),
    enhanceLevel: 0,
    classRestrict: s === 'weapon' ? classRestrict : null
  };
}

export function enhance(item, rng = Math.random) {
  if (item.enhanceLevel >= 9) return { ok: false, reason: 'max' };
  // 失败不掉级，仅耗材料
  const success = rng() < 0.7;
  if (success) item.enhanceLevel += 1;
  return { ok: success, level: item.enhanceLevel };
}

export function reforge(item, rng = Math.random, pity = { count: 0 }) {
  // 保底：连续 5 次未提升品质则强制提升一档
  const idx = QUALITIES.indexOf(item.quality);
  if (pity.count >= 5 && idx < QUALITIES.length - 1) {
    item.quality = QUALITIES[idx + 1];
    pity.count = 0;
    return { quality: item.quality, pity: true };
  }
  const newAffix = rollAffixes(rng, 1)[0];
  if (item.affixes.length) item.affixes[Math.floor(rng() * item.affixes.length)] = newAffix;
  else item.affixes.push(newAffix);
  pity.count += 1;
  return { quality: item.quality, pity: false };
}

// loot.js - 掉落权重/Boss保底/独立掉落分配（纯逻辑）
import { createItem, QUALITY_WEIGHTS } from './items.js';

export const BOSS_WEIGHTS = { white: 0, green: 0, blue: 75, purple: 20, orange: 5 };

export function rollLoot({ rng = Math.random, isBoss = false, count = 1 } = {}) {
  const out = [];
  for (let i = 0; i < count; i++) {
    const weights = isBoss ? BOSS_WEIGHTS : QUALITY_WEIGHTS;
    out.push(createItem({ rng, quality: rollQualityFrom(rng, weights) }));
  }
  return out;
}

function rollQualityFrom(rng, weights) {
  const total = Object.values(weights).reduce((a, b) => a + b, 0);
  let r = rng() * total;
  for (const q of Object.keys(weights)) {
    r -= weights[q];
    if (r <= 0) return q;
  }
  return 'blue';
}

// 独立掉落：每个玩家一份，互不可见
export function assignIndependentDrops(players, drops) {
  return players.map((p, i) => ({ playerId: p.id, items: drops[i] || [] }));
}

// inventory.js - 背包60/仓库200/分解/对比（纯逻辑）
export const BAG_SIZE = 60;
export const STASH_SIZE = 200;

export function createInventory() {
  return { bag: [], stash: [], materials: 0, gold: 0 };
}

export function addItem(inv, item) {
  if (inv.bag.length >= BAG_SIZE) return { ok: false, reason: 'bag_full' };
  inv.bag.push(item);
  return { ok: true };
}

export function moveToStash(inv, itemId) {
  const idx = inv.bag.findIndex(i => i.id === itemId);
  if (idx < 0) return { ok: false, reason: 'not_found' };
  if (inv.stash.length >= STASH_SIZE) return { ok: false, reason: 'stash_full' };
  const [it] = inv.bag.splice(idx, 1);
  inv.stash.push(it);
  return { ok: true };
}

export function dismantle(inv, itemId) {
  const idx = inv.bag.findIndex(i => i.id === itemId);
  if (idx < 0) return { ok: false, reason: 'not_found' };
  const [it] = inv.bag.splice(idx, 1);
  const gain = { white: 1, green: 2, blue: 4, purple: 8, orange: 16 }[it.quality] || 1;
  inv.materials += gain;
  return { ok: true, materials: gain };
}

export function dismantleWhiteGreen(inv) {
  let n = 0;
  inv.bag = inv.bag.filter(it => {
    if (it.quality === 'white' || it.quality === 'green') { n++; inv.materials += it.quality === 'white' ? 1 : 2; return false; }
    return true;
  });
  return { count: n };
}

export function compare(a, b) {
  const score = it => it.affixes.reduce((s, af) => s + af.value, 0) + it.enhanceLevel * 2;
  return { better: score(b) > score(a), delta: score(b) - score(a) };
}

// save.js - 存档序列化/版本迁移/CRC/双备份（纯逻辑，落盘由调用方注入）
export const SAVE_VERSION = 1;

export function crc32(str) {
  let c, crc = 0xFFFFFFFF;
  for (let i = 0; i < str.length; i++) {
    c = (crc ^ str.charCodeAt(i)) & 0xFF;
    for (let k = 0; k < 8; k++) c = c & 1 ? (c >>> 1) ^ 0xEDB88320 : c >>> 1;
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

export function serialize(state) {
  const body = { ...state, version: SAVE_VERSION };
  const json = JSON.stringify(body);
  return { json, crc: crc32(json) };
}

export function deserialize(json, expectedCrc) {
  if (crc32(json) !== expectedCrc) return { ok: false, reason: 'crc_mismatch' };
  const data = JSON.parse(json);
  return { ok: true, data: migrate(data) };
}

export function migrate(data) {
  if (!data.version) data.version = 1;
  // 未来版本迁移在此追加
  return data;
}

export function writeDualBackup(storage, key, payload) {
  storage.setItem(key + '.a', JSON.stringify(payload));
  storage.setItem(key + '.b', JSON.stringify(payload));
}

export function readWithFallback(storage, key) {
  for (const suffix of ['.a', '.b']) {
    const raw = storage.getItem(key + suffix);
    if (!raw) continue;
    try {
      const p = JSON.parse(raw);
      const r = deserialize(p.json, p.crc);
      if (r.ok) return r;
    } catch (e) { /* 继续尝试备份 */ }
  }
  return { ok: false, reason: 'both_corrupt' };
}

// coop.js - 多人动态缩放/扶起/掉队传送（纯逻辑）
export const SCALE = {
  1: { hp: 1.0, dmg: 1.0, gold: 1.0 },
  2: { hp: 1.6, dmg: 1.15, gold: 1.25 },
  3: { hp: 2.1, dmg: 1.25, gold: 1.45 },
  4: { hp: 2.6, dmg: 1.35, gold: 1.65 }
};

export function scaleFor(playerCount, isBoss = false) {
  const s = SCALE[Math.min(4, Math.max(1, playerCount))];
  return { hp: s.hp * (isBoss ? 1.1 : 1), dmg: s.dmg, gold: s.gold };
}

export function downPlayer(player, nowMs) {
  player.down = true;
  player.downAt = nowMs;
  return player;
}

export function tryRevive(downed, reviver, nowMs) {
  if (!downed.down) return { ok: false };
  if (nowMs - downed.downAt >= 3000) {
    downed.down = false;
    downed.hp = Math.round(downed.maxHp * 0.3);
    return { ok: true };
  }
  return { ok: false, remaining: 3000 - (nowMs - downed.downAt) };
}

export function teleportIfLeftBehind(player, leader, dtMs) {
  const dist = Math.abs(player.x - leader.x);
  if (dist > 600) {
    player.teleportTimer = (player.teleportTimer || 0) + dtMs;
    if (player.teleportTimer >= 3000) {
      player.x = leader.x;
      player.y = leader.y;
      player.teleportTimer = 0;
      return true;
    }
  } else {
    player.teleportTimer = 0;
  }
  return false;
}
